def transform(grid):
    """Transform the grid: find the main vertical line of key color, change interrupting 9s to 4s"""
    if not grid or not grid[0]:
        return grid

    h = len(grid)
    w = len(grid[0])

    # Find the key color (non-background color)
    key_color = None
    for row in grid:
        for val in row:
            if val != 9:
                key_color = val
                break
        if key_color:
            break

    if not key_color:
        return grid

    # Find columns with key_color segments
    # First, identify columns where key_color forms potential vertical structure
    # Exclude columns that are purely 5s without interruption (these don't have 9s to turn to 4s)

    color_counts = {}
    for c in range(w):
        count = sum(1 for r in range(h) if grid[r][c] == key_color)
        color_counts[c] = count

    # Find the column with the most key_color cells (main vertical line)
    main_col = max(color_counts, key=color_counts.get)

    # Apply transformation: change interrupting 9s to 4s
    result = [row[:] for row in grid]

    for r in range(h):
        if result[r][main_col] == 9:
            # Check if this 9 interrupts a segment (has key_color above or below)
            above_key = (r > 0 and result[r-1][main_col] == key_color)
            below_key = (r < h-1 and result[r+1][main_col] == key_color)
            if above_key or below_key:
                result[r][main_col] = 4

    return result

