def transform(grid):
    """Transform the grid: find the main vertical line of key color, change interrupting 9s to 4s"""
    if not grid or not grid[0]:
        return grid

    h = len(grid)
    w = len(grid[0])

    # Find the key color (non-background color)
    key_color = None
    for row in grid:
        for val in row:
            if val != 9:
                key_color = val
                break
        if key_color:
            break

    if not key_color:
        return grid

    # Find the column with the most key_color cells (main vertical line)
    color_counts = {}
    for c in range(w):
        count = sum(1 for r in range(h) if grid[r][c] == key_color)
        color_counts[c] = count

    # Find the main vertical column (mode of color_counts)
    main_col = max(color_counts, key=color_counts.get)

    # Apply transformation: for each row with 9 at main_col,
    # change to 4 if there's key_color somewhere above AND sometime below
    result = [row[:] for row in grid]

    for r in range(h):
        if result[r][main_col] == 9:
            # Check if key_color exists at some position above this row at main_col
            has_above = any(grid[c][main_col] == key_color for c in range(r))
            # Check if key_color exists at some position below this row at main_col
            has_below = any(grid[c][main_col] == key_color for c in range(r+1, h))

            if has_above and has_below:
                result[r][main_col] = 4

    return result

